cd /tmp/claude-0/-home-user-chick-contact-system/9737741b-6ce5-5409-92dc-67b8f29eb2a7/scratchpad && mkdir -p locktest && cd locktest && touch .lock && cat > probe.py <<'EOF'
import fcntl, os, sys
# does an exec'd child inherit flock(1)'s fd, and does a fresh open+flock block?
inherited=[]
for fd in os.listdir('/proc/self/fd'):
    fd=int(fd)
    try:
        st=os.fstat(fd)
        if (st.st_ino, st.st_dev)==(os.stat('.lock').st_ino, os.stat('.lock').st_dev): inherited.append(fd)
    except OSError: pass
print("inherited fds on .lock:", inherited)
f=open('.lock','a+')
try:
    fcntl.flock(f, fcntl.LOCK_EX|fcntl.LOCK_NB); print("fresh fd: lock acquired")
except OSError as e:
    print("fresh fd: would block:", e)
if inherited:
    fcntl.flock(inherited[0], fcntl.LOCK_EX|fcntl.LOCK_NB); print("inherited fd: flock succeeded (conversion)")
EOF
timeout 10 flock .lock python3 probe.py; echo "exit $?"; echo ---; timeout 10 python3 probe.py; echo "exit $?"

